import type { RevalidationArgs } from "@kasperrt/smolter/react";

export function shouldRevalidate({ reason, actionResult }: RevalidationArgs) {
  if (reason === "action" && actionResult &&
      typeof actionResult === "object" && "changed" in actionResult) {
    return actionResult.changed !== false;
  }

  return true;
}

const revalidate = useRevalidator();

await revalidate({ route: "/items/:id" });
await revalidate({ route: ["root", "/items/:id"] });

// Preact application entry
mountApplication(routes, { ...root, loaderPath: "/session" });

// Refresh only root data from a component
const revalidate = useRevalidator();
await revalidate({ route: "root" });

// Custom layout integration
const unregister = router.registerRevalidator("account-layout", refreshAccount);
